public static void main(Args _args)
{
    AVASalesQuotationController_PrintInMemory salesQuotationController_PrintInMemory = AVASalesQuotationController_PrintInMemory::construct();

    salesQuotationController_PrintInMemory.parmavaPrintInMemory(NoYes::Yes);
    salesQuotationController_PrintInMemory.parmAVAReportRecord(_args.record());

    salesQuotationController_PrintInMemory.initArgs(_args, PrintMgmtDocType::construct(PrintMgmtDocumentType::Quotation).getDefaultReportFormat());

    salesQuotationController_PrintInMemory.startOperation();
}

